window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"pl-roots":{src:"act:roots",route:"#/atlas/honey/roots",cta:"Open the Root Kingdoms",title:"Act V · The Root Kingdoms",body:"21 stops on this road, from “graph / gram (write / record)” to “cred (believe)”."},"li-u55":{src:"concept:58:concept",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record)",body:"Greek graphein = to write. One root unlocks three suffix families: -graph (the instrument/method), -gram (the written thing), and -graphy (the art or study of writing something)."},"lc-u55-0":{src:"concept:58:cards:0",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record) · The Root",body:"Greek graphein = to write. When you see -graph or -gram, ask: what is being written or recorded? Telegraph = write from far. Monograph = written about one thing. Autograph = written by oneself. One root family, unlimited words."},"lc-u55-1":{src:"concept:58:cards:1",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record) · -graph = The Instrument/Method",body:"Seismograph = records earthquakes. Cardiograph = records heart. Photograph = photo (light) + graph = written by light. Lithograph = lithos (stone) = printed from stone. Stenograph = stenos (narrow) = narrow fast writing."},"lc-u55-2":{src:"concept:58:cards:2",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record) · -gram = The Thing Written",body:"Telegram = the distant message. Anagram = ana (again) = letters rearranged. Epigram = epi (upon) = a witty inscription. Monogram = mono (one) = initials written. Cryptogram = crypto (hidden) = a coded message."},"lc-u55-3":{src:"concept:58:cards:3",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record) · -graphy = The Art/Study",body:"Calligraphy = kalli (beautiful) = beautiful writing. Choreography = choreia (dance) = the art of composing dances. Topography = topos (place) = describing physical features. Stenography = shorthand writing."},"lc-u55-4":{src:"concept:58:cards:4",route:"#/stop/u55",cta:"Open this stop",title:"graph / gram (write / record) · -grapher = The Person",body:"Stenographer = shorthand typist. Choreographer = designs dances. Photographer = takes photographs. Biographer = writes a life story. Lexicographer = writes dictionaries (a word that describes itself!). The -er agent suffix pairs with the Greek -graph- root."},"uq-u55-0":{src:"unit:u55:qs:0",route:"#/stop/u55",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “graph / gram (write / record)”?",opts:["Greek graphein = to write.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],after:"From “graph / gram (write / record)”."}},"uq-u55-3":{src:"unit:u55:qs:3",route:"#/stop/u55",cta:"Open this stop",title:"Whose hook?",play:{q:"“A ▁▁▁ GRAPHS the ground's shaking — remember 'graph' means to write or draw.” — which word is this hook about?",opts:["seismograph","cardiograph","lithograph","stenograph"],after:"From “graph / gram (write / record)”."}},"wd-seismograph":{src:"concept:58:words:0:def",route:"#/word/seismograph",cta:"Open the word card",title:"seismograph",roman:"SYZ-muh-graf",body:"a measuring instrument for detecting and measuring the intensity and direction and duration of movements of the ground (as an earthquake)",clip:1},"wx-seismograph":{src:"concept:58:words:0:ex",route:"#/word/seismograph",cta:"Open the word card",title:"In a sentence · seismograph",body:"Scientists studied the seismograph readings to determine the earthquake's magnitude and origin.",clip:1},"wh-seismograph":{src:"concept:58:words:0:hook",route:"#/word/seismograph",cta:"Open the word card",title:"Remember it · seismograph",body:"A seismoGRAPH GRAPHS the ground's shaking — remember 'graph' means to write or draw."},"wd-cardiograph":{src:"concept:58:words:1:def",route:"#/word/cardiograph",cta:"Open the word card",title:"cardiograph",roman:"KAR-dee-oh-graf",body:"medical instrument that records electric currents associated with contractions of the heart",clip:1},"wx-cardiograph":{src:"concept:58:words:1:ex",route:"#/word/cardiograph",cta:"Open the word card",title:"In a sentence · cardiograph",body:"The technician attached electrodes to the patient's chest before turning on the cardiograph.",clip:1},"wh-cardiograph":{src:"concept:58:words:1:hook",route:"#/word/cardiograph",cta:"Open the word card",title:"Remember it · cardiograph",body:"CARDIO (heart) + GRAPH (write/record) = the machine that writes the heart's story."},"wd-lithograph":{src:"concept:58:words:2:def",route:"#/word/lithograph",cta:"Open the word card",title:"lithograph",roman:"LIH-thuh-graf",body:"a print produced by lithography",clip:1},"wx-lithograph":{src:"concept:58:words:2:ex",route:"#/word/lithograph",cta:"Open the word card",title:"In a sentence · lithograph",body:"The museum displayed an original lithograph by the famous artist, showing incredible detail despite being over a century old.",clip:1},"wh-lithograph":{src:"concept:58:words:2:hook",route:"#/word/lithograph",cta:"Open the word card",title:"Remember it · lithograph",body:"A lithograph is writing on stone — 'litho' (stone) + 'graph' (write), like ancient graffiti on rock."},"wo-lithograph":{src:"lore:lithograph:0",route:"#/word/lithograph",cta:"Open the word card",title:"Where it comes from · lithograph",body:"Greek lithos = stone + graphein = to write/draw"},"wd-anagram":{src:"concept:58:words:4:def",route:"#/word/anagram",cta:"Open the word card",title:"anagram",roman:"A-nuh-gram",body:"a word or phrase spelled by rearranging the letters of another word or phrase",clip:1},"wx-anagram":{src:"concept:58:words:4:ex",route:"#/word/anagram",cta:"Open the word card",title:"In a sentence · anagram",body:'The puzzle book challenged readers to find that "listen" is a perfect anagram of the word "silent."',clip:1},"wh-anagram":{src:"concept:58:words:4:hook",route:"#/word/anagram",cta:"Open the word card",title:"Remember it · anagram",body:"An ANAGRAM writes (GRAM) letters AGAIN (ANA) in a new order — only ONE 'n'!"},"wd-epigram":{src:"concept:58:words:5:def",route:"#/word/epigram",cta:"Open the word card",title:"epigram",roman:"EH-puh-gram",body:"a witty saying",clip:1},"wx-epigram":{src:"concept:58:words:5:ex",route:"#/word/epigram",cta:"Open the word card",title:"In a sentence · epigram",body:"The teacher had written an Oscar Wilde epigram on the board: 'I can resist everything except temptation,' which made the whole class laugh.",clip:1},"wh-epigram":{src:"concept:58:words:5:hook",route:"#/word/epigram",cta:"Open the word card",title:"Remember it · epigram",body:"An EPIgram is a short bit of writing — like a telegram for the mind"},"wo-epigram":{src:"lore:epigram:0",route:"#/word/epigram",cta:"Open the word card",title:"Where it comes from · epigram",body:"Greek epigramma = inscription, from graphein = to write"},"wd-monogram":{src:"concept:58:words:6:def",route:"#/word/monogram",cta:"Open the word card",title:"monogram",roman:"MAH-nuh-gram",body:"a graphic symbol consisting of 2 or more letters combined (usually your initials); printed on stationery or embroidered on clothing",clip:1},"wx-monogram":{src:"concept:58:words:6:ex",route:"#/word/monogram",cta:"Open the word card",title:"In a sentence · monogram",body:"The bride's initials were sewn as a golden monogram on each of the linen napkins.",clip:1},"wh-monogram":{src:"concept:58:words:6:hook",route:"#/word/monogram",cta:"Open the word card",title:"Remember it · monogram",body:"A MONOgram is ONE set of letters — one GRAM of alphabet ink on your shirt."},"wo-monogram":{src:"lore:monogram:0",route:"#/word/monogram",cta:"Open the word card",title:"Where it comes from · monogram",body:"Greek monos=single + gramma=letter"},"wd-calligraphy":{src:"concept:58:words:8:def",route:"#/word/calligraphy",cta:"Open the word card",title:"calligraphy",roman:"kuh-LIH-gruh-fee",body:"beautiful handwriting",clip:1},"wx-calligraphy":{src:"concept:58:words:8:ex",route:"#/word/calligraphy",cta:"Open the word card",title:"In a sentence · calligraphy",body:"She spent the summer learning calligraphy so she could address all the graduation party envelopes by hand.",clip:1},"wh-calligraphy":{src:"concept:58:words:8:hook",route:"#/word/calligraphy",cta:"Open the word card",title:"Remember it · calligraphy",body:"CALLIgraphy: CALLI sounds like 'calling' beauty onto the page — double L for double beauty."},"wo-calligraphy":{src:"lore:calligraphy:0",route:"#/word/calligraphy",cta:"Open the word card",title:"Where it comes from · calligraphy",body:"Greek kalos = beautiful + graphein = to write"},"wd-choreography":{src:"concept:58:words:9:def",route:"#/word/choreography",cta:"Open the word card",title:"choreography",roman:"kaw-ree-AH-gruh-fee",body:"a show involving artistic dancing",clip:1},"wx-choreography":{src:"concept:58:words:9:ex",route:"#/word/choreography",cta:"Open the word card",title:"In a sentence · choreography",body:"The choreography for the school musical was so impressive that the audience leapt to their feet in applause.",clip:1},"wh-choreography":{src:"concept:58:words:9:hook",route:"#/word/choreography",cta:"Open the word card",title:"Remember it · choreography",body:"CHOREOGRAPHY = choreo + GRAPHY — like photography, it's always spelled with PH."},"wo-choreography":{src:"lore:choreography:0",route:"#/word/choreography",cta:"Open the word card",title:"Where it comes from · choreography",body:"Greek choros = dance + graphein = to write"},"wd-topography":{src:"concept:58:words:10:def",route:"#/word/topography",cta:"Open the word card",title:"topography",roman:"tuh-PAH-gruh-fee",body:"the configuration of a surface and the relations among its man-made and natural features",clip:1},"wx-topography":{src:"concept:58:words:10:ex",route:"#/word/topography",cta:"Open the word card",title:"In a sentence · topography",body:"The hikers studied the topography of the mountain range before choosing the safest trail.",clip:1},"wh-topography":{src:"concept:58:words:10:hook",route:"#/word/topography",cta:"Open the word card",title:"Remember it · topography",body:"TOP-O-GRAPHY: describe (GRAPH) a place (TOPO) from the TOP down."},"wo-topography":{src:"lore:topography:0",route:"#/word/topography",cta:"Open the word card",title:"Where it comes from · topography",body:"Greek topos = place + graphein = to write/describe"},"wd-monograph":{src:"concept:58:words:15:def",route:"#/word/monograph",cta:"Open the word card",title:"monograph",roman:"MAH-nuh-graf",body:"a detailed and documented treatise on a particular subject",clip:1},"wx-monograph":{src:"concept:58:words:15:ex",route:"#/word/monograph",cta:"Open the word card",title:"In a sentence · monograph",body:"The scientist spent three years writing a monograph on the behavior of deep-sea bioluminescent creatures.",clip:1},"wh-monograph":{src:"concept:58:words:15:hook",route:"#/word/monograph",cta:"Open the word card",title:"Remember it · monograph",body:"A MONOgraph is ONE topic written up thoroughly — one GRAPH of knowledge."},"wo-monograph":{src:"lore:monograph:0",route:"#/word/monograph",cta:"Open the word card",title:"Where it comes from · monograph",body:"Greek monos=single + graphein=to write"},"wd-autobiography":{src:"concept:58:words:16:def",route:"#/word/autobiography",cta:"Open the word card",title:"autobiography",roman:"aw-tuh-beye-AH-gruh-fee",body:"a biography of yourself",clip:1},"wx-autobiography":{src:"concept:58:words:16:ex",route:"#/word/autobiography",cta:"Open the word card",title:"In a sentence · autobiography",body:"Maya Angelou's autobiography describes her childhood in the American South with vivid and moving detail.",clip:1},"wh-autobiography":{src:"concept:58:words:16:hook",route:"#/word/autobiography",cta:"Open the word card",title:"Remember it · autobiography",body:"AUTO + BIO + GRAPHY: a self (auto) life (bio) writing (graphy) — PH makes the F sound, not plain F."},"wo-autobiography":{src:"lore:autobiography:0",route:"#/word/autobiography",cta:"Open the word card",title:"Where it comes from · autobiography",body:"Greek autos = self + bios = life + graphein = to write"},"li-u56":{src:"concept:59:concept",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice)",body:"Greek phonē = sound, voice. The ph spelling is an absolute Greek signal — never f in learned sound words. This root appears in music, linguistics, and technology."},"lc-u56-0":{src:"concept:59:cards:0",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice) · The Root",body:"Greek phonē = sound, voice. The ph = /f/ spelling is the Greek identity card. Never write f for sound words that come from Greek. Phonics = the study of sound-letter relationships. Phonetics = science of speech sounds. Phoneme = the smallest unit of sound."},"lc-u56-1":{src:"concept:59:cards:1",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice) · Good vs Bad Sound",body:"Greek eu = good; kako = bad. Euphony = pleasant harmonious sound. Cacophony = harsh, unpleasant noise. Symphony = syn (together) + phony = sounds in harmony. Polyphony = poly (many) = many simultaneous voices. Homophone = homo (same) = same sound, different spelling."},"lc-u56-2":{src:"concept:59:cards:2",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice) · Sound Instruments",body:"Microphone = mikros (small) + phone = makes small voices big. Saxophone = invented by Adolphe Sax + phone = his instrument's sound. Megaphone = megas (large) = makes voice large. Xylophone = xylo (wood) + phone = wooden sound. All these instruments work with sound — all spell the sound with ph."},"lc-u56-3":{src:"concept:59:cards:3",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice) · Language of Sound",body:"Phonics = sound-letter study. Phonetics = speech sound science. Homophone = same sound. Dysphonia (dys- = bad + phonia) = difficulty with voice production. Aphasia (a- = without + phasis = speech) = loss of ability to speak or understand language."},"lc-u56-4":{src:"concept:59:cards:4",route:"#/stop/u56",cta:"Open this stop",title:"phon / phone (sound / voice) · Musical ph Words",body:"Philharmonic = phil (love) + harmonikos = loving harmony. The ph in the phil- component is also a Greek spelling signal. Saxophone keeps phone despite being named after a person. The Greek root outlasts any individual's name in English spelling."},"uq-u56-3":{src:"unit:u56:qs:3",route:"#/stop/u56",cta:"Open this stop",title:"Whose hook?",play:{q:"“CACO-PHONY: bad (caco) PHONE (phon) call — all noise and no sense, spelled with phony at the end.” — which word is this hook about?",opts:["cacophony","euphony","symphony","polyphony"],after:"From “phon / phone (sound / voice)”."}},"wd-cacophony":{src:"concept:59:words:0:def",route:"#/word/cacophony",cta:"Open the word card",title:"cacophony",roman:"k-a-k-AH-f-uh-n-ee",body:"is a harsh discordance of sound",clip:1},"wx-cacophony":{src:"concept:59:words:0:ex",route:"#/word/cacophony",cta:"Open the word card",title:"In a sentence · cacophony",body:"The construction site next to the library created such a cacophony that students could barely concentrate on their reading.",clip:1},"wh-cacophony":{src:"concept:59:words:0:hook",route:"#/word/cacophony",cta:"Open the word card",title:"Remember it · cacophony",body:"CACO-PHONY: bad (caco) PHONE (phon) call — all noise and no sense, spelled with phony at the end."},"wo-cacophony":{src:"lore:cacophony:0",route:"#/word/cacophony",cta:"Open the word card",title:"Where it comes from · cacophony",body:"Greek kakos = bad + phone = sound/voice"},"wd-euphony":{src:"concept:59:words:1:def",route:"#/word/euphony",cta:"Open the word card",title:"euphony",roman:"YOO-fuh-nee",body:"any agreeable (pleasing and harmonious) sounds",clip:1},"wx-euphony":{src:"concept:59:words:1:ex",route:"#/word/euphony",cta:"Open the word card",title:"In a sentence · euphony",body:"Birdsong and rippling water blended into a euphony that made the whole garden feel peaceful.",clip:1},"wh-euphony":{src:"concept:59:words:1:hook",route:"#/word/euphony",cta:"Open the word card",title:"Remember it · euphony",body:"Euphony = EU + PHONY — but unlike a phony friend, euphony is genuinely pleasant to the ear!"},"wd-symphony":{src:"concept:59:words:2:def",route:"#/word/symphony",cta:"Open the word card",title:"symphony",roman:"SIH-mfuh-nee",body:"a long and complex sonata for symphony orchestra",clip:1},"wx-symphony":{src:"concept:59:words:2:ex",route:"#/word/symphony",cta:"Open the word card",title:"In a sentence · symphony",body:"we heard the Vienna symphony",clip:1},"wh-symphony":{src:"concept:59:words:2:hook",route:"#/word/symphony",cta:"Open the word card",title:"Remember it · symphony",body:"A symPHONy is sounds (PHON) together — not symphAny, the O holds the note!"},"wo-symphony":{src:"lore:symphony:0",route:"#/word/symphony",cta:"Open the word card",title:"Where it comes from · symphony",body:"Greek symphonia = syn=together + phone=sound"},"wd-saxophone":{src:"concept:59:words:5:def",route:"#/word/saxophone",cta:"Open the word card",title:"saxophone",roman:"SA-ksuh-fohn",body:"a single-reed woodwind with a conical bore",clip:1},"wx-saxophone":{src:"concept:59:words:5:ex",route:"#/word/saxophone",cta:"Open the word card",title:"In a sentence · saxophone",body:"The jazz musician played a mellow saxophone solo that filled the entire club with warm, golden sound.",clip:1},"wh-saxophone":{src:"concept:59:words:5:hook",route:"#/word/saxophone",cta:"Open the word card",title:"Remember it · saxophone",body:"SAX-O-PHONE: the Sax makes a PHONE call — no 'a' in the middle, just an o."},"wo-saxophone":{src:"lore:saxophone:0",route:"#/word/saxophone",cta:"Open the word card",title:"Where it comes from · saxophone",body:"Proper name Sax + Greek phone = sound/voice"},"wd-megaphone":{src:"concept:59:words:6:def",route:"#/word/megaphone",cta:"Open the word card",title:"megaphone",roman:"MEH-guh-fohn",body:"a cone-shaped acoustic device held to the mouth to intensify and direct the human voice",clip:1},"wx-megaphone":{src:"concept:59:words:6:ex",route:"#/word/megaphone",cta:"Open the word card",title:"In a sentence · megaphone",body:"The coach grabbed a megaphone to shout instructions to his players on the far end of the field.",clip:1},"wh-megaphone":{src:"concept:59:words:6:hook",route:"#/word/megaphone",cta:"Open the word card",title:"Remember it · megaphone",body:"A MEGAPHONE makes your PHONE (voice) MEGA loud — 'phone' always ends in P-H-O-N-E, never 'fone.'"},"wo-megaphone":{src:"lore:megaphone:0",route:"#/word/megaphone",cta:"Open the word card",title:"Where it comes from · megaphone",body:"Greek megas = great + phone = sound/voice"},"wd-xylophone":{src:"concept:59:words:7:def",route:"#/word/xylophone",cta:"Open the word card",title:"xylophone",roman:"ZEYE-luh-fohn",body:"a percussion instrument with wooden bars tuned to produce a chromatic scale and with resonators; played with small mallets",clip:1},"wx-xylophone":{src:"concept:59:words:7:ex",route:"#/word/xylophone",cta:"Open the word card",title:"In a sentence · xylophone",body:"The kindergartner proudly played a simple tune on the colorful xylophone during the school recital.",clip:1},"wh-xylophone":{src:"concept:59:words:7:hook",route:"#/word/xylophone",cta:"Open the word card",title:"Remember it · xylophone",body:"A XYLOPHONE makes PHONe sounds from XYLO (wooden) bars — always start with X, not Z!"},"wo-xylophone":{src:"lore:xylophone:0",route:"#/word/xylophone",cta:"Open the word card",title:"Where it comes from · xylophone",body:"Greek xylon = wood + phone = sound"},"wd-phonics":{src:"concept:59:words:8:def",route:"#/word/phonics",cta:"Open the word card",title:"phonics",roman:"FAH-nihks",body:"teaching reading by training beginners to associate letters with their sound values",clip:1},"wx-phonics":{src:"concept:59:words:8:ex",route:"#/word/phonics",cta:"Open the word card",title:"In a sentence · phonics",body:"By using phonics in first grade, the students quickly learned to decode new words by sounding them out letter by letter.",clip:1},"wh-phonics":{src:"concept:59:words:8:hook",route:"#/word/phonics",cta:"Open the word card",title:"Remember it · phonics",body:"PHONICS is about PHONE-sounds — PHONe starts with the same sound-root."},"wd-phonetics":{src:"concept:59:words:9:def",route:"#/word/phonetics",cta:"Open the word card",title:"phonetics",roman:"fuh-NEH-tihks",body:"the branch of acoustics concerned with speech processes including its production and perception and acoustic analysis",clip:1},"wx-phonetics":{src:"concept:59:words:9:ex",route:"#/word/phonetics",cta:"Open the word card",title:"In a sentence · phonetics",body:"Studying phonetics helped the language student understand exactly how to position her tongue and lips to produce new sounds.",clip:1},"wh-phonetics":{src:"concept:59:words:9:hook",route:"#/word/phonetics",cta:"Open the word card",title:"Remember it · phonetics",body:"PHONETICS studies speech sounds — PHONETIC+S: add S for the whole science of sounds."},"wo-phonetics":{src:"lore:phonetics:0",route:"#/word/phonetics",cta:"Open the word card",title:"Where it comes from · phonetics",body:"Greek phōnētikos = of sounds"},"wd-homophone":{src:"concept:59:words:10:def",route:"#/word/homophone",cta:"Open the word card",title:"homophone",roman:"HOH-moh-fohn",body:"two words are homophones if they are pronounced the same way but differ in meaning or spelling or both (e.g. bare and bear)",clip:1},"wx-homophone":{src:"concept:59:words:10:ex",route:"#/word/homophone",cta:"Open the word card",title:"In a sentence · homophone",body:"The words 'knight' and 'night' are homophones because they sound identical but are spelled differently.",clip:1},"wh-homophone":{src:"concept:59:words:10:hook",route:"#/word/homophone",cta:"Open the word card",title:"Remember it · homophone",body:"A homoPHONE sounds the same (PHONE = sound) — 'knight' and 'night' ring identically in your ear even though spelled differently."},"wo-homophone":{src:"lore:homophone:0",route:"#/word/homophone",cta:"Open the word card",title:"Where it comes from · homophone",body:"Greek homos = same + phone = sound, voice"},"wd-phoneme":{src:"concept:59:words:11:def",route:"#/word/phoneme",cta:"Open the word card",title:"phoneme",roman:"FOH-neem",body:"(linguistics) one of a small set of speech sounds that are distinguished by the speakers of a particular language",clip:1},"wx-phoneme":{src:"concept:59:words:11:ex",route:"#/word/phoneme",cta:"Open the word card",title:"In a sentence · phoneme",body:"Changing a single phoneme can completely alter the meaning of a word, as when 'bat' becomes 'bad.'",clip:1},"wh-phoneme":{src:"concept:59:words:11:hook",route:"#/word/phoneme",cta:"Open the word card",title:"Remember it · phoneme",body:"A PHONEME is the smallest sound unit — PHON+EME: think of it as an EXTREME tiny sound."},"wd-philharmonic":{src:"concept:59:words:12:def",route:"#/word/philharmonic",cta:"Open the word card",title:"philharmonic",roman:"fih-lhah-RMAH-nihk",body:"a large orchestra; can perform symphonies",clip:1},"wx-philharmonic":{src:"concept:59:words:12:ex",route:"#/word/philharmonic",cta:"Open the word card",title:"In a sentence · philharmonic",body:"The seventh-grade music class attended a concert performed by the city's philharmonic and were stunned by the power of one hundred instruments playing together.",clip:1},"wh-philharmonic":{src:"concept:59:words:12:hook",route:"#/word/philharmonic",cta:"Open the word card",title:"Remember it · philharmonic",body:"PHILharmonic: a PHIL-anthropist LOVES people; philharmonic LOVES harmony"},"wo-philharmonic":{src:"lore:philharmonic:0",route:"#/word/philharmonic",cta:"Open the word card",title:"Where it comes from · philharmonic",body:"Greek philos (loving) + harmonikos (harmonic, musical)"},"wd-dysphonia":{src:"concept:59:words:13:def",route:"#/word/dysphonia",cta:"Open the word card",title:"dysphonia",roman:"dis-FOH-nee-uh",body:"speech disorder attributable to a disorder of phonation",clip:1},"wx-dysphonia":{src:"concept:59:words:13:ex",route:"#/word/dysphonia",cta:"Open the word card",title:"In a sentence · dysphonia",body:"The singer's dysphonia left her unable to perform for months as she rested her strained vocal cords.",clip:1},"wh-dysphonia":{src:"concept:59:words:13:hook",route:"#/word/dysphonia",cta:"Open the word card",title:"Remember it · dysphonia",body:"DYSphonia means your PHONE (voice) has a DYSfunctional signal — speech is broken."},"wd-aphasia":{src:"concept:59:words:14:def",route:"#/word/aphasia",cta:"Open the word card",title:"aphasia",roman:"uh-FAY-zhuh",body:"inability to use or understand language (spoken or written) because of a brain lesion",clip:1},"wx-aphasia":{src:"concept:59:words:14:ex",route:"#/word/aphasia",cta:"Open the word card",title:"In a sentence · aphasia",body:"After suffering a stroke, the journalist developed aphasia and had to relearn how to speak and read.",clip:1},"wh-aphasia":{src:"concept:59:words:14:hook",route:"#/word/aphasia",cta:"Open the word card",title:"Remember it · aphasia",body:"A-PHASIA = A person who can't PHASE out words properly"},"wo-aphasia":{src:"lore:aphasia:0",route:"#/word/aphasia",cta:"Open the word card",title:"Where it comes from · aphasia",body:"Greek 'aphasia' = speechlessness, from 'a-' = without + 'phasis' = speech, from 'phanai' = to speak"},"li-u57":{src:"concept:60:concept",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease)",body:"Greek pathos = feeling, suffering. In medicine it means disease; in literature and rhetoric it means emotion. Two meanings, one root — context tells you which applies."},"lc-u57-0":{src:"concept:60:cards:0",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease) · The Root",body:"Pathos = feeling, suffering. Sympathy = sym (with) = feeling with someone. Empathy = em (in) = feeling as if inside someone's experience. Antipathy = anti (against) = feeling against = deep dislike. Apathy = a- (without) = feeling nothing at all."},"lc-u57-1":{src:"concept:60:cards:1",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease) · The pathos Scale",body:"Apathy (no feeling) → sympathy (feeling alongside) → empathy (feeling as if it's yours). These three form a scale of emotional connection. In a bee: apathy = A-P-A-T-H-Y; sympathy = S-Y-M-P-A-T-H-Y; empathy = E-M-P-A-T-H-Y. Same ending, different prefix each time."},"lc-u57-2":{src:"concept:60:cards:2",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease) · Medical -pathy Words",body:"Neuropathy = neuro + pathy = nerve disease. Osteopathy = bone/tissue manipulation treatment. Psychopathy = psycho + pathy = mental disorder. Homeopathy = homeo (same) + pathy = treating with similar substances. Cardiopathy = heart disease."},"lc-u57-3":{src:"concept:60:cards:3",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease) · Pathology Branch",body:"Pathology = path + logy = the study of disease. Pathogen = path + gen = a disease-causing organism. Pathological = relating to disease; also means compulsive (a pathological liar). Pathologist = a doctor who analyzes disease causes."},"lc-u57-4":{src:"concept:60:cards:4",route:"#/stop/u57",cta:"Open this stop",title:"path / pathy (suffering / feeling / disease) · Pathos in Rhetoric",body:"Pathos = the quality in a work that evokes pity or sadness — one of Aristotle's three rhetorical appeals (alongside logos = reason and ethos = character). Bathos = an abrupt drop from the elevated to the trivial — the anti-pathos. Both Greek words, both kept their Greek spelling in English."},"uq-u57-3":{src:"unit:u57:qs:3",route:"#/stop/u57",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: feel the SAME (sym) PATHos—you walk the same feeling path” — which word is this hook about?",opts:["sympathy","empathy","antipathy","apathy"],after:"From “path / pathy (suffering / feeling / disease)”."}},"wd-sympathy":{src:"concept:60:words:0:def",route:"#/word/sympathy",cta:"Open the word card",title:"sympathy",roman:"SIH-mpuh-thee",body:"an inclination to support or be loyal to or to agree with an opinion",clip:1},"wx-sympathy":{src:"concept:60:words:0:ex",route:"#/word/sympathy",cta:"Open the word card",title:"In a sentence · sympathy",body:"When Jordan broke her leg before the championship, her teammates sent a card full of sympathy and encouragement.",clip:1},"wh-sympathy":{src:"concept:60:words:0:hook",route:"#/word/sympathy",cta:"Open the word card",title:"Remember it · sympathy",body:"SYMPATHY: feel the SAME (sym) PATHos—you walk the same feeling path"},"wo-sympathy":{src:"lore:sympathy:0",route:"#/word/sympathy",cta:"Open the word card",title:"Where it comes from · sympathy",body:"Greek sympatheia, from syn-(together)+pathos(feeling, suffering)"},"wd-empathy":{src:"concept:60:words:1:def",route:"#/word/empathy",cta:"Open the word card",title:"empathy",roman:"EH-mpuh-thee",body:"understanding and entering into another's feelings",clip:1},"wx-empathy":{src:"concept:60:words:1:ex",route:"#/word/empathy",cta:"Open the word card",title:"In a sentence · empathy",body:"Her empathy for the injured stray cat led her to spend hours nursing it back to health.",clip:1},"wh-empathy":{src:"concept:60:words:1:hook",route:"#/word/empathy",cta:"Open the word card",title:"Remember it · empathy",body:"EMPATHY: Enter My Pal's Agony To Help You — no extra 'h' after 'em'."},"wd-apathy":{src:"concept:60:words:3:def",route:"#/word/apathy",cta:"Open the word card",title:"apathy",roman:"A-puh-thee",body:"an absence of emotion or enthusiasm",clip:1},"wx-apathy":{src:"concept:60:words:3:ex",route:"#/word/apathy",cta:"Open the word card",title:"In a sentence · apathy",body:"The coach worried that the team's apathy after three straight losses would make it impossible to prepare them for the championship game.",clip:1},"wh-apathy":{src:"concept:60:words:3:hook",route:"#/word/apathy",cta:"Open the word card",title:"Remember it · apathy",body:"A-PATH-Y: apathy is being on a path with no destination — no feeling, no direction, just 'a' + 'path' + 'y'."},"wd-psychopathy":{src:"concept:60:words:6:def",route:"#/word/psychopathy",cta:"Open the word card",title:"psychopathy",roman:"seye-KAH-puh-thee",body:"any disease of the mind; the psychological state of someone who has emotional or behavioral problems serious enough to require psychiatric intervention",clip:1},"wx-psychopathy":{src:"concept:60:words:6:ex",route:"#/word/psychopathy",cta:"Open the word card",title:"In a sentence · psychopathy",body:"Researchers studying psychopathy have found that certain brain differences may explain why some individuals feel no guilt or compassion.",clip:1},"wh-psychopathy":{src:"concept:60:words:6:hook",route:"#/word/psychopathy",cta:"Open the word card",title:"Remember it · psychopathy",body:"PSYCHOpaTHY — the mind's disease ends in -PATHY, like empathy but darker."},"wo-psychopathy":{src:"lore:psychopathy:0",route:"#/word/psychopathy",cta:"Open the word card",title:"Where it comes from · psychopathy",body:"Greek psyche = mind + pathos = suffering"},"wd-homeopathy":{src:"concept:60:words:7:def",route:"#/word/homeopathy",cta:"Open the word card",title:"homeopathy",roman:"hoh-mee-oh-PA-thee",body:"a method of treating disease with small amounts of remedies that, in large amounts in healthy people, produce symptoms similar to those being treated",clip:1},"wx-homeopathy":{src:"concept:60:words:7:ex",route:"#/word/homeopathy",cta:"Open the word card",title:"In a sentence · homeopathy",body:"Some people turn to homeopathy as an alternative treatment, believing that highly diluted natural substances can trigger the body's healing response.",clip:1},"wh-homeopathy":{src:"concept:60:words:7:hook",route:"#/word/homeopathy",cta:"Open the word card",title:"Remember it · homeopathy",body:"HOMEOPATHY: treat disease with a SIMILAR remedy — spot the E-O in the middle."},"wo-homeopathy":{src:"lore:homeopathy:0",route:"#/word/homeopathy",cta:"Open the word card",title:"Where it comes from · homeopathy",body:"Greek homoios = similar + pathos = suffering"},"wd-cardiopathy":{src:"concept:60:words:8:def",route:"#/word/cardiopathy",cta:"Open the word card",title:"cardiopathy",roman:"kar-dee-OP-uh-thee",body:"a disease of the heart",clip:1},"wx-cardiopathy":{src:"concept:60:words:8:ex",route:"#/word/cardiopathy",cta:"Open the word card",title:"In a sentence · cardiopathy",body:"The cardiologist explained that the elderly man's cardiopathy had weakened his heart muscle over many years of high blood pressure.",clip:1},"wh-cardiopathy":{src:"concept:60:words:8:hook",route:"#/word/cardiopathy",cta:"Open the word card",title:"Remember it · cardiopathy",body:"CARDIO (heart) + PATHY (disease) = heart disease."},"wo-cardiopathy":{src:"lore:cardiopathy:0",route:"#/word/cardiopathy",cta:"Open the word card",title:"Where it comes from · cardiopathy",body:"Greek kardia = heart + pathos = suffering/disease"},"wd-pathology":{src:"concept:60:words:9:def",route:"#/word/pathology",cta:"Open the word card",title:"pathology",roman:"puh-THAH-luh-jee",body:"the branch of medical science that studies the causes and nature and effects of diseases",clip:1},"wx-pathology":{src:"concept:60:words:9:ex",route:"#/word/pathology",cta:"Open the word card",title:"In a sentence · pathology",body:"The forensic pathology report revealed that the ancient mummy had suffered from a bone disease.",clip:1},"wh-pathology":{src:"concept:60:words:9:hook",route:"#/word/pathology",cta:"Open the word card",title:"Remember it · pathology",body:"PATHology is the LOGY (study) of the PATH disease takes — one G, not two."},"wo-pathology":{src:"lore:pathology:0",route:"#/word/pathology",cta:"Open the word card",title:"Where it comes from · pathology",body:"Greek pathos = disease + logos = study"},"wd-pathogen":{src:"concept:60:words:10:def",route:"#/word/pathogen",cta:"Open the word card",title:"pathogen",roman:"PA-thuh-juhn",body:"any disease-producing agent (especially a virus or bacterium or other microorganism)",clip:1},"wx-pathogen":{src:"concept:60:words:10:ex",route:"#/word/pathogen",cta:"Open the word card",title:"In a sentence · pathogen",body:"Scientists worked around the clock to identify the pathogen responsible for the mysterious outbreak.",clip:1},"wh-pathogen":{src:"concept:60:words:10:hook",route:"#/word/pathogen",cta:"Open the word card",title:"Remember it · pathogen",body:"A PATHogen GENErates disease — remember PATH + O + GEN like a disease-generating gene."},"wo-pathogen":{src:"lore:pathogen:0",route:"#/word/pathogen",cta:"Open the word card",title:"Where it comes from · pathogen",body:"Greek pathos = disease + genesis = origin, produce"},"wd-pathological":{src:"concept:60:words:11:def",route:"#/word/pathological",cta:"Open the word card",title:"pathological",roman:"pa-thuh-LAH-jih-kuhl",body:"of or relating to the practice of pathology",clip:1},"wx-pathological":{src:"concept:60:words:11:ex",route:"#/word/pathological",cta:"Open the word card",title:"In a sentence · pathological",body:"pathological laboratory",clip:1},"wh-pathological":{src:"concept:60:words:11:hook",route:"#/word/pathological",cta:"Open the word card",title:"Remember it · pathological",body:"A PATHOLOGICAl liar follows a sick path — end with ‑ICAL not ‑ICLE."},"wd-bathos":{src:"concept:60:words:14:def",route:"#/word/bathos",cta:"Open the word card",title:"bathos",roman:"BAY-thohs",body:"triteness or triviality of style",clip:1},"wx-bathos":{src:"concept:60:words:14:ex",route:"#/word/bathos",cta:"Open the word card",title:"In a sentence · bathos",body:"The heroic poem collapsed into bathos when the knight's climactic battle cry was interrupted by a sneeze.",clip:1},"wh-bathos":{src:"concept:60:words:14:hook",route:"#/word/bathos",cta:"Open the word card",title:"Remember it · bathos",body:"BATHOS: the writing takes a bath and comes out flat and trivial"},"wo-bathos":{src:"lore:bathos:0",route:"#/word/bathos",cta:"Open the word card",title:"Where it comes from · bathos",body:"Greek bathos = depth"},"wd-pathos":{src:"concept:60:words:15:def",route:"#/word/pathos",cta:"Open the word card",title:"pathos",roman:"PAY-thahs",body:"a quality that arouses emotions (especially pity or sorrow)",clip:1},"wx-pathos":{src:"concept:60:words:15:ex",route:"#/word/pathos",cta:"Open the word card",title:"In a sentence · pathos",body:"the film captured all the pathos of their situation",clip:1},"wh-pathos":{src:"concept:60:words:15:hook",route:"#/word/pathos",cta:"Open the word card",title:"Remember it · pathos",body:"PATHOS stirs PATH of emotion in your heart — PATH + OS: P-A-T-H-O-S."},"li-u58":{src:"concept:61:concept",route:"#/stop/u58",cta:"Open this stop",title:"chron (time)",body:"Greek khronos = time. All chron- words relate to time. The ch = /k/ sound is a Greek signal. The god Kronos (Time) gave his name to this root — and to the planet Saturn in Roman mythology."},"lc-u58-0":{src:"concept:61:cards:0",route:"#/stop/u58",cta:"Open this stop",title:"chron (time) · The Root",body:"Greek Khronos = time (and the god of time). Chron- always appears with the ch = /k/ Greek spelling. Chronological = in time order. Anachronism = ana (against) + chron = something out of its proper time (a smartphone in a medieval movie)."},"lc-u58-1":{src:"concept:61:cards:1",route:"#/stop/u58",cta:"Open this stop",title:"chron (time) · Time Order Words",body:"Chronological = arranged by time. Diachronic (dia = through) = studied across time (how language changes). Synchronic (syn = together) = studied at one moment in time. Isochronal (iso = equal) = happening at equal time intervals."},"lc-u58-2":{src:"concept:61:cards:2",route:"#/stop/u58",cta:"Open this stop",title:"chron (time) · Measuring Time",body:"Chronometer = chron + meter = instrument that measures time precisely. Used by sailors for navigation — required the most accurate timekeeping available. Chronograph = chron + graph = records/writes time (a stopwatch-type instrument). Chronoscope = chron + scope = looks at and measures time."},"lc-u58-3":{src:"concept:61:cards:3",route:"#/stop/u58",cta:"Open this stop",title:"chron (time) · Time Stories",body:"Chronicle = a time-ordered record of events. Chronic = chron + -ic = lasting over a long time (chronic illness = ongoing). Anachronistic = out of its proper time period. Synchronicity = meaningful coincidence of events happening at the same time (Carl Jung's concept)."},"lc-u58-4":{src:"concept:61:cards:4",route:"#/stop/u58",cta:"Open this stop",title:"chron (time) · The ch=/k/ Greek Signal in chron",body:"In Greek-origin words, ch = /k/: choreography, chemistry, chronology, chaos, character, choir, chorus. This is one of the most reliable Greek spelling signals. Hearing /k/ in a learned word = look for ch, not k or c, as the spelling."},"uq-u58-3":{src:"unit:u58:qs:3",route:"#/stop/u58",cta:"Open this stop",title:"Whose hook?",play:{q:"“An ▁▁▁ fights against (ANA) CHRONOS (time) — keep 'chron' for time and end it with '-ism', not '-izm'.” — which word is this hook about?",opts:["anachronism","synchronize","chronometer","chronograph"],after:"From “chron (time)”."}},"wd-chronometer":{src:"concept:61:words:2:def",route:"#/word/chronometer",cta:"Open the word card",title:"chronometer",roman:"kruh-NOM-ih-ter",body:"an accurate clock (especially used in navigation)",clip:1},"wx-chronometer":{src:"concept:61:words:2:ex",route:"#/word/chronometer",cta:"Open the word card",title:"In a sentence · chronometer",body:"The ship's navigator relied on the chronometer to calculate their exact position in the middle of the Pacific Ocean.",clip:1},"wh-chronometer":{src:"concept:61:words:2:hook",route:"#/word/chronometer",cta:"Open the word card",title:"Remember it · chronometer",body:"CHRONO (time) + METER (measure) = time measurer."},"wo-chronometer":{src:"lore:chronometer:0",route:"#/word/chronometer",cta:"Open the word card",title:"Where it comes from · chronometer",body:"Greek khronos = time + metron = measure"},"wd-chronograph":{src:"concept:61:words:3:def",route:"#/word/chronograph",cta:"Open the word card",title:"chronograph",roman:"KROH-noh-graf",body:"an accurate timer for recording time",clip:1},"wx-chronograph":{src:"concept:61:words:3:ex",route:"#/word/chronograph",cta:"Open the word card",title:"In a sentence · chronograph",body:"The Olympic coach used a chronograph to record each swimmer's exact finishing time down to the hundredth of a second.",clip:1},"wh-chronograph":{src:"concept:61:words:3:hook",route:"#/word/chronograph",cta:"Open the word card",title:"Remember it · chronograph",body:"A chronograph GRAPHS time — CHRONOgraph writes (graphs) time for you."},"wd-chronicle":{src:"concept:61:words:4:def",route:"#/word/chronicle",cta:"Open the word card",title:"chronicle",roman:"KRAH-nih-kuhl",body:"a record or narrative description of past events",clip:1},"wx-chronicle":{src:"concept:61:words:4:ex",route:"#/word/chronicle",cta:"Open the word card",title:"In a sentence · chronicle",body:"The elderly historian decided to write a detailed chronicle of the town's founding, recording every important event from the first settlers' arrival to the present day.",clip:1},"wh-chronicle":{src:"concept:61:words:4:hook",route:"#/word/chronicle",cta:"Open the word card",title:"Remember it · chronicle",body:"A CHRONICLE tracks time in little bites — 'chron' for time, '-icle' like a tiny article."},"wo-chronicle":{src:"lore:chronicle:0",route:"#/word/chronicle",cta:"Open the word card",title:"Where it comes from · chronicle",body:"Greek khronos = time + -icle (diminutive/noun suffix)"},"wd-chronic":{src:"concept:61:words:5:def",route:"#/word/chronic",cta:"Open the word card",title:"chronic",roman:"KRAH-nihk",body:"being long-lasting and recurrent or characterized by long suffering",clip:1},"wx-chronic":{src:"concept:61:words:5:ex",route:"#/word/chronic",cta:"Open the word card",title:"In a sentence · chronic",body:"After years of playing competitive soccer without proper rest, the athlete developed chronic knee pain that forced her to visit a physical therapist every week just to stay comfortable enough to practice.",clip:1},"wh-chronic":{src:"concept:61:words:5:hook",route:"#/word/chronic",cta:"Open the word card",title:"Remember it · chronic",body:"CHRONIC pain lasts through time — 'chron' = time, just like in chronology."},"wd-chronological":{src:"concept:61:words:8:def",route:"#/word/chronological",cta:"Open the word card",title:"chronological",roman:"krah-nuh-LAH-jih-kuhl",body:"relating to or arranged according to temporal order",clip:1},"wx-chronological":{src:"concept:61:words:8:ex",route:"#/word/chronological",cta:"Open the word card",title:"In a sentence · chronological",body:"The teacher asked the class to arrange the historical events in chronological order, starting with the earliest date and working forward through the decades to the present day.",clip:1},"wh-chronological":{src:"concept:61:words:8:hook",route:"#/word/chronological",cta:"Open the word card",title:"Remember it · chronological",body:"CHRONOLOGICAL order follows time's logic — 'chron' + 'logical' = time makes logical sense."},"wo-chronological":{src:"lore:chronological:0",route:"#/word/chronological",cta:"Open the word card",title:"Where it comes from · chronological",body:"Greek khronos = time + logos = study"},"wd-anachronistic":{src:"concept:61:words:11:def",route:"#/word/anachronistic",cta:"Open the word card",title:"anachronistic",roman:"uh-na-kruh-NIH-stihk",body:"chronologically misplaced",clip:1},"wx-anachronistic":{src:"concept:61:words:11:ex",route:"#/word/anachronistic",cta:"Open the word card",title:"In a sentence · anachronistic",body:"English public schools are anachronistic",clip:1},"wh-anachronistic":{src:"concept:61:words:11:hook",route:"#/word/anachronistic",cta:"Open the word card",title:"Remember it · anachronistic",body:"A knight with aCHRONOMETER is ANAchronistic — against the flow of time."},"li-u59":{src:"concept:62:concept",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape)",body:"Greek morphē = form, shape. Morph- appears in biology, linguistics, mythology, and technology. The shape-shifting nature of the root makes it appear in transformation vocabulary across every field."},"lc-u59-0":{src:"concept:62:cards:0",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape) · The Root",body:"Greek morphē = form, shape. Metamorphosis = meta (change) + morph (form) + -osis (process) = a complete change of form. Amorphous (a- + morph) = without shape = shapeless. Polymorphous (poly- + morph) = having many forms. Morphology = the study of form."},"lc-u59-1":{src:"concept:62:cards:1",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape) · Biological Morph Words",body:"Metamorphosis = caterpillar → butterfly = complete form change. Dimorphic (di- = two) = existing in two distinct forms. Anthropomorphic = anthropo + morphic = having human form. Geomorphic = geo + morphic = having earth-shaped features. Isomorphic = iso (equal) = having the same form."},"lc-u59-2":{src:"concept:62:cards:2",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape) · Linguistic Morph Words",body:"Morpheme = the smallest meaningful unit in language (-tion, un-, run). Morphology = the study of word forms and structure. Allomorph (allo- = different) = a different form of the same morpheme (the plural -s in cats vs -es in boxes). These are the building blocks of every word in this book."},"lc-u59-3":{src:"concept:62:cards:3",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape) · Technology & Culture",body:"Morph (verb) = to transform (as in computer graphics). Anamorphic = ana (back) + morph = distorted image that becomes clear from a specific angle. Anthropomorphism = attributing human characteristics to non-humans (giving animals human emotions in stories)."},"lc-u59-4":{src:"concept:62:cards:4",route:"#/stop/u59",cta:"Open this stop",title:"morph (form / shape) · Spelling the ph",body:"The -ph- in morph = /f/. This is Greek phi (φ). Morphine (Morpheus = god of dreams = shapes of dreams) = the drug named after the dream god. Morpheus himself = the god of dreams who could take any human form. The drug, the god, and the root all share the /morf/ sound — always spelled with ph."},"wd-amorphous":{src:"concept:62:words:1:def",route:"#/word/amorphous",cta:"Open the word card",title:"amorphous",roman:"uh-MAW-rfuhs",body:"having no definite form or distinct shape",clip:1},"wx-amorphous":{src:"concept:62:words:1:ex",route:"#/word/amorphous",cta:"Open the word card",title:"In a sentence · amorphous",body:"amorphous clouds of insects",clip:1},"wh-amorphous":{src:"concept:62:words:1:hook",route:"#/word/amorphous",cta:"Open the word card",title:"Remember it · amorphous",body:"Amorphous has 'morph' inside — morph means shape, and amorphous has NO shape."},"wo-amorphous":{src:"lore:amorphous:0",route:"#/word/amorphous",cta:"Open the word card",title:"Where it comes from · amorphous",body:"Greek amorphos = without form (a- = without, morphe = form)"},"wd-polymorphous":{src:"concept:62:words:2:def",route:"#/word/polymorphous",cta:"Open the word card",title:"polymorphous",roman:"pol-ee-MOR-fus",body:"relating to the crystallization of a compound in two or more different forms",clip:1},"wx-polymorphous":{src:"concept:62:words:2:ex",route:"#/word/polymorphous",cta:"Open the word card",title:"In a sentence · polymorphous",body:"polymorphous crystallization",clip:1},"wh-polymorphous":{src:"concept:62:words:2:hook",route:"#/word/polymorphous",cta:"Open the word card",title:"Remember it · polymorphous",body:"POLY + MORPH + OUS: many morphs (shapes) — think of a shapeshifter with many forms."},"wd-morphology":{src:"concept:62:words:3:def",route:"#/word/morphology",cta:"Open the word card",title:"morphology",roman:"maw-RFAH-luh-jee",body:"the branch of biology that deals with the structure of animals and plants",clip:1},"wx-morphology":{src:"concept:62:words:3:ex",route:"#/word/morphology",cta:"Open the word card",title:"In a sentence · morphology",body:"In science class, we studied the morphology of insects, comparing the body structures of beetles and butterflies.",clip:1},"wh-morphology":{src:"concept:62:words:3:hook",route:"#/word/morphology",cta:"Open the word card",title:"Remember it · morphology",body:"MORPHOLOGY: the study of form — keep the PH because Greek PHilosophers loved studying PHorms."},"wo-morphology":{src:"lore:morphology:0",route:"#/word/morphology",cta:"Open the word card",title:"Where it comes from · morphology",body:"Greek morphe = form + logos = study"},"wd-dimorphic":{src:"concept:62:words:4:def",route:"#/word/dimorphic",cta:"Open the word card",title:"dimorphic",roman:"deye-MAW-rfihk",body:"occurring or existing in two different forms",clip:1},"wx-dimorphic":{src:"concept:62:words:4:ex",route:"#/word/dimorphic",cta:"Open the word card",title:"In a sentence · dimorphic",body:"The biology textbook explained that many bird species are dimorphic, with males displaying vivid, colorful feathers while females appear in dull, muted browns for camouflage.",clip:1},"wh-dimorphic":{src:"concept:62:words:4:hook",route:"#/word/dimorphic",cta:"Open the word card",title:"Remember it · dimorphic",body:"DiMORPHic means two (DI) shapes (MORPH) — like a Transformer with two forms."},"wo-dimorphic":{src:"lore:dimorphic:0",route:"#/word/dimorphic",cta:"Open the word card",title:"Where it comes from · dimorphic",body:"Greek di = two + morphe = form"},"wd-anthropomorphic":{src:"concept:62:words:5:def",route:"#/word/anthropomorphic",cta:"Open the word card",title:"anthropomorphic",roman:"a-nthruh-puh-MAW-rfihk",body:"suggesting human characteristics for animals or inanimate things",clip:1},"wx-anthropomorphic":{src:"concept:62:words:5:ex",route:"#/word/anthropomorphic",cta:"Open the word card",title:"In a sentence · anthropomorphic",body:"The animated film featured anthropomorphic animals who spoke, wore clothes, and faced very human problems.",clip:1},"wh-anthropomorphic":{src:"concept:62:words:5:hook",route:"#/word/anthropomorphic",cta:"Open the word card",title:"Remember it · anthropomorphic",body:"MORPHIC means shaped — anthropoMORPHIC means shaped like a human; think of a MORPHing robot taking human form."},"wo-anthropomorphic":{src:"lore:anthropomorphic:0",route:"#/word/anthropomorphic",cta:"Open the word card",title:"Where it comes from · anthropomorphic",body:"Greek anthropos = human + morphe = form/shape"},"wd-isomorphic":{src:"concept:62:words:7:def",route:"#/word/isomorphic",cta:"Open the word card",title:"isomorphic",roman:"eye-soh-MOR-fik",body:"having similar appearance but genetically different",clip:1},"wx-isomorphic":{src:"concept:62:words:7:ex",route:"#/word/isomorphic",cta:"Open the word card",title:"In a sentence · isomorphic",body:"Two graphs are isomorphic if one can be rearranged to look exactly like the other.",clip:1},"wh-isomorphic":{src:"concept:62:words:7:hook",route:"#/word/isomorphic",cta:"Open the word card",title:"Remember it · isomorphic",body:"ISO + MORPHIC — 'equal shape,' add -IC to isomorph: i-s-o-m-o-r-p-h-i-c."},"wd-morpheme":{src:"concept:62:words:8:def",route:"#/word/morpheme",cta:"Open the word card",title:"morpheme",roman:"MOR-feem",body:"minimal meaningful language unit; it cannot be divided into smaller meaningful units",clip:1},"wx-morpheme":{src:"concept:62:words:8:ex",route:"#/word/morpheme",cta:"Open the word card",title:"In a sentence · morpheme",body:"The teacher explained that the word 'unhappy' contains two morphemes: 'un' and 'happy.'",clip:1},"wh-morpheme":{src:"concept:62:words:8:hook",route:"#/word/morpheme",cta:"Open the word card",title:"Remember it · morpheme",body:"A MORPHEME ends in -EME like phoneme or grapheme — it's a team of linguistic units."},"wd-allomorph":{src:"concept:62:words:9:def",route:"#/word/allomorph",cta:"Open the word card",title:"allomorph",roman:"A-luh-mawrf",body:"any of several different crystalline forms of the same chemical compound",clip:1},"wx-allomorph":{src:"concept:62:words:9:ex",route:"#/word/allomorph",cta:"Open the word card",title:"In a sentence · allomorph",body:"calcium carbonate occurs in the allomorphs calcite and aragonite",clip:1},"wh-allomorph":{src:"concept:62:words:9:hook",route:"#/word/allomorph",cta:"Open the word card",title:"Remember it · allomorph",body:"An allomorph is ANOTHER FORM (morph) — like a shapeshifter with a double-L disguise at the start."},"wo-allomorph":{src:"lore:allomorph:0",route:"#/word/allomorph",cta:"Open the word card",title:"Where it comes from · allomorph",body:"Greek allos = other + morphe = form/shape"},"wd-anthropomorphism":{src:"concept:62:words:10:def",route:"#/word/anthropomorphism",cta:"Open the word card",title:"anthropomorphism",roman:"a-nthruh-puh-MAW-rfih-zuhm",body:"the representation of objects (especially a god) as having human form or traits",clip:1},"wx-anthropomorphism":{src:"concept:62:words:10:ex",route:"#/word/anthropomorphism",cta:"Open the word card",title:"In a sentence · anthropomorphism",body:"The author used anthropomorphism to give the forest animals human emotions and the ability to speak.",clip:1},"wh-anthropomorphism":{src:"concept:62:words:10:hook",route:"#/word/anthropomorphism",cta:"Open the word card",title:"Remember it · anthropomorphism",body:"AnthropoMORPHISM: when you see a dog SMILing, that's anthropomorphISM — giving it human form, ending in -ISM."},"wd-morphine":{src:"concept:62:words:12:def",route:"#/word/morphine",cta:"Open the word card",title:"morphine",roman:"m-AW-r-f-ee-n",body:"is a narcotic used as a pain-killer or sedative",clip:1},"wx-morphine":{src:"concept:62:words:12:ex",route:"#/word/morphine",cta:"Open the word card",title:"In a sentence · morphine",body:"After the surgery, the patient was given morphine to manage the intense pain during recovery.",clip:1},"wh-morphine":{src:"concept:62:words:12:hook",route:"#/word/morphine",cta:"Open the word card",title:"Remember it · morphine",body:"MORPHINE: named for Morpheus the dream god — keep the PH or the spelling won't sleep well."},"wo-morphine":{src:"lore:morphine:0",route:"#/word/morphine",cta:"Open the word card",title:"Where it comes from · morphine",body:"Named for Morpheus, Greek god of dreams, because the drug brings sleep"},"li-u60":{src:"concept:63:concept",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine)",body:"Greek skopein = to look at. Every -scope word is an instrument for examining something. The root tells you what is being examined; -scope tells you it is a viewing/examining device."},"lc-u60-0":{src:"concept:63:cards:0",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine) · The Root",body:"Greek skopein = to look at. Kaleidoscope = kalos (beautiful) + eidos (form) + -scope = looks at beautiful forms. Microscope = mikros (small) = looks at tiny things. Telescope = tele (far) = looks at distant things. Periscope = peri (around) = looks around corners or over surfaces."},"lc-u60-1":{src:"concept:63:cards:1",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine) · Medical Scopes",body:"Stethoscope (stethos = chest) = listens to the chest. Endoscope (endo- = within) = looks inside the body. Laparoscope (laparo- = abdomen) = looks inside the abdomen. Ophthalmoscope (ophthalmos = eye) = examines the interior of the eye. Bronchoscope = examines the bronchial tubes."},"lc-u60-2":{src:"concept:63:cards:2",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine) · Science Scopes",body:"Oscilloscope (oscillare = to swing) = displays wave patterns. Spectroscope (spectrum = image) = analyzes light spectra. Cystoscope (kystis = bladder) = examines the bladder. Colonoscope = examines the colon. Each scope is named for exactly what it looks at — the root tells you everything."},"lc-u60-3":{src:"concept:63:cards:3",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine) · Horoscope — The Exception",body:"Horoscope (hora = hour/season + -scope) = looking at the hour of birth to tell the future. The hora here is not a body part or scientific field — it is time. Horoscope is the only common -scope word where the root is not something being physically examined."},"lc-u60-4":{src:"concept:63:cards:4",route:"#/stop/u60",cta:"Open this stop",title:"scop / scope (see / examine) · Kaleidoscope Spelling",body:"K-A-L-E-I-D-O-S-C-O-P-E — three combined Greek roots, fourteen letters. Break it: kali- (beautiful) + -eido- (form, from eidos) + -scope (look). The -ei- in kaleid- = /eye/ sound. The sc- in -scope = /sk/. Knowing the three parts makes the spelling manageable."},"uq-u60-3":{src:"unit:u60:qs:3",route:"#/stop/u60",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ shows BEAUTIFUL (kalos) SHAPES (eidos) to SEE (scope).” — which word is this hook about?",opts:["kaleidoscope","microscope","telescope","periscope"],after:"From “scop / scope (see / examine)”."}},"wd-endoscope":{src:"concept:63:words:5:def",route:"#/word/endoscope",cta:"Open the word card",title:"endoscope",roman:"EH-ndoh-skohp",body:"a long slender medical instrument for examining the interior of a bodily organ or performing minor surgery",clip:1},"wx-endoscope":{src:"concept:63:words:5:ex",route:"#/word/endoscope",cta:"Open the word card",title:"In a sentence · endoscope",body:"The doctor used an endoscope to examine the patient's stomach without requiring major surgery.",clip:1},"wh-endoscope":{src:"concept:63:words:5:hook",route:"#/word/endoscope",cta:"Open the word card",title:"Remember it · endoscope",body:"An ENDOscope lets doctors look INSIDE — ENDO=within, SCOPE=look, just like a telescope looks far."},"wo-endoscope":{src:"lore:endoscope:0",route:"#/word/endoscope",cta:"Open the word card",title:"Where it comes from · endoscope",body:"Greek endon=within + skopein=to look"},"wd-ophthalmoscope":{src:"concept:63:words:7:def",route:"#/word/ophthalmoscope",cta:"Open the word card",title:"ophthalmoscope",roman:"ah-FTHA-lmuh-skohp",body:"medical instrument for examining the retina of the eye",clip:1},"wx-ophthalmoscope":{src:"concept:63:words:7:ex",route:"#/word/ophthalmoscope",cta:"Open the word card",title:"In a sentence · ophthalmoscope",body:"The doctor shone light through the ophthalmoscope to carefully examine the blood vessels at the back of the patient's eye.",clip:1},"wh-ophthalmoscope":{src:"concept:63:words:7:hook",route:"#/word/ophthalmoscope",cta:"Open the word card",title:"Remember it · ophthalmoscope",body:"An OPHTHALMOSCOPE looks INTO the eye — OPHTHALM (eye) + SCOPE (look), a tool that sees inside."},"wo-ophthalmoscope":{src:"lore:ophthalmoscope:0",route:"#/word/ophthalmoscope",cta:"Open the word card",title:"Where it comes from · ophthalmoscope",body:"Greek ophthalmos = eye + skopein = to look"},"wd-oscilloscope":{src:"concept:63:words:8:def",route:"#/word/oscilloscope",cta:"Open the word card",title:"oscilloscope",roman:"aw-SIH-luh-skohp",body:"electronic equipment that provides visual images of varying electrical quantities",clip:1},"wx-oscilloscope":{src:"concept:63:words:8:ex",route:"#/word/oscilloscope",cta:"Open the word card",title:"In a sentence · oscilloscope",body:"The physics class used an oscilloscope to see the wave pattern produced by a vibrating guitar string.",clip:1},"wh-oscilloscope":{src:"concept:63:words:8:hook",route:"#/word/oscilloscope",cta:"Open the word card",title:"Remember it · oscilloscope",body:"An OSCILLOSCOPE lets you SEE oscillations — double-L plus SCOPE: you look (scope) at the swings (LL)."},"wo-oscilloscope":{src:"lore:oscilloscope:0",route:"#/word/oscilloscope",cta:"Open the word card",title:"Where it comes from · oscilloscope",body:"Latin oscillare = to swing + Greek skopein = to look at"},"wd-spectroscope":{src:"concept:63:words:9:def",route:"#/word/spectroscope",cta:"Open the word card",title:"spectroscope",roman:"SPEK-troh-skohp",body:"an optical instrument for spectrographic analysis",clip:1},"wx-spectroscope":{src:"concept:63:words:9:ex",route:"#/word/spectroscope",cta:"Open the word card",title:"In a sentence · spectroscope",body:"Using a spectroscope, the student split white light into a rainbow of individual colors.",clip:1},"wh-spectroscope":{src:"concept:63:words:9:hook",route:"#/word/spectroscope",cta:"Open the word card",title:"Remember it · spectroscope",body:"SPECTRO + SCOPE: you SCOPE out the SPECTRUM — spectro-scope, two familiar pieces."},"wd-horoscope":{src:"concept:63:words:12:def",route:"#/word/horoscope",cta:"Open the word card",title:"horoscope",roman:"HAW-ruh-skohp",body:"a prediction of someone's future based on the relative positions of the planets",clip:1},"wx-horoscope":{src:"concept:63:words:12:ex",route:"#/word/horoscope",cta:"Open the word card",title:"In a sentence · horoscope",body:"She read her horoscope every morning, though she never really believed the stars could predict her day.",clip:1},"wh-horoscope":{src:"concept:63:words:12:hook",route:"#/word/horoscope",cta:"Open the word card",title:"Remember it · horoscope",body:"A horoSCOPE SCOPES out your future — spell it horo+scope, the O in horo is the full moon."},"wo-horoscope":{src:"lore:horoscope:0",route:"#/word/horoscope",cta:"Open the word card",title:"Where it comes from · horoscope",body:"Greek hora = hour/season + skopein = to observe"},"wd-bronchoscope":{src:"concept:63:words:13:def",route:"#/word/bronchoscope",cta:"Open the word card",title:"bronchoscope",roman:"brah-nkuh-SKOHP",body:"a slender tubular instrument used to examine the bronchial tubes",clip:1},"wx-bronchoscope":{src:"concept:63:words:13:ex",route:"#/word/bronchoscope",cta:"Open the word card",title:"In a sentence · bronchoscope",body:"The doctor used a bronchoscope to look inside the patient's airways and find the cause of his persistent cough.",clip:1},"wh-bronchoscope":{src:"concept:63:words:13:hook",route:"#/word/bronchoscope",cta:"Open the word card",title:"Remember it · bronchoscope",body:"A bronchOSCOPE lets doctors SCOPE out your windpipe — the SCOPE part sees all."},"wo-bronchoscope":{src:"lore:bronchoscope:0",route:"#/word/bronchoscope",cta:"Open the word card",title:"Where it comes from · bronchoscope",body:"Greek bronkhos = windpipe + Greek skopein = to look at"},"li-u61":{src:"concept:64:concept",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study)",body:"Greek logos = word, reason, study. One of the most productive roots in all of English — it appears as the -logy study suffix, the -log/-logue conversation words, and even in theological vocabulary."},"lc-u61-0":{src:"concept:64:cards:0",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study) · The Root",body:"Greek logos = word, reason, study. Dialogue (dia = between) = words between two people. Monologue (mono = one) = one person's long speech. Prologue (pro = before) = words before the main work. Epilogue (epi = upon/after) = words after the main work."},"lc-u61-1":{src:"concept:64:cards:1",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study) · -logy = Study Of",body:"This suffix is explored fully in C37 (-ology/-ologist). Key connections here: tautology (tauto = same) = saying the same thing twice. Eulogy (eu = good) = good words spoken of someone (usually at a funeral). Neologism (neo = new + logos) = a newly coined word."},"lc-u61-2":{src:"concept:64:cards:2",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study) · Demagogue & Pedagogue",body:"Demagogue (demos = people + ago = lead) = one who leads the people through manipulation. Pedagogue (pais = child + ago) = one who leads children = a teacher. Note: these end in -agogue = one who leads, not -logue = speech. Related by the -og- but different suffix."},"lc-u61-3":{src:"concept:64:cards:3",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study) · Theology & Related Words",body:'Theos = god + logos = theology = the study of God. Theocracy = theos + kratos = rule by God/religious law. Monotheism, polytheism, atheism all use theos. The logos root independently means "the Word" in biblical contexts — the opening of the Gospel of John: "In the beginning was the logos."'},"lc-u61-4":{src:"concept:64:cards:4",route:"#/stop/u61",cta:"Open this stop",title:"log / logy (word / reason / study) · Spelling -logue vs -log",body:"American English prefers -log: catalog, dialog, prolog (though prologue is also accepted). British English uses -logue: catalogue, dialogue, prologue. In a competition: both spellings may be accepted — but know which dictionary the bee uses (Merriam-Webster for Scripps = American spellings)."},"uq-u61-3":{src:"unit:u61:qs:3",route:"#/stop/u61",cta:"Open this stop",title:"Whose hook?",play:{q:"“A ▁▁▁ is ONE person's LOGUE (speech) — one mouth, lots of words, add the UE.” — which word is this hook about?",opts:["monologue","dialogue","prologue","epilogue"],after:"From “log / logy (word / reason / study)”."}},"wd-prologue":{src:"concept:64:words:2:def",route:"#/word/prologue",cta:"Open the word card",title:"prologue",roman:"PROH-lahg",body:"an introduction to a play",clip:1},"wx-prologue":{src:"concept:64:words:2:ex",route:"#/word/prologue",cta:"Open the word card",title:"In a sentence · prologue",body:"The prologue hinted at the dark events that would unfold later in the play.",clip:1},"wh-prologue":{src:"concept:64:words:2:hook",route:"#/word/prologue",cta:"Open the word card",title:"Remember it · prologue",body:"A prOLOGUE opens the show — remember the 'ue' like the curtain cue before the play begins."},"wd-analogy":{src:"concept:64:words:4:def",route:"#/word/analogy",cta:"Open the word card",title:"analogy",roman:"uh-NA-luh-jee",body:"an inference that if things agree in some respects they probably agree in others",clip:1},"wx-analogy":{src:"concept:64:words:4:ex",route:"#/word/analogy",cta:"Open the word card",title:"In a sentence · analogy",body:"the operation of a computer presents and interesting analogy to the working of the brain",clip:1},"wh-analogy":{src:"concept:64:words:4:hook",route:"#/word/analogy",cta:"Open the word card",title:"Remember it · analogy",body:"An ANALOGY uses LOGIC (log) to draw a comparison — find the LOG in anaLOGy."},"wo-analogy":{src:"lore:analogy:0",route:"#/word/analogy",cta:"Open the word card",title:"Where it comes from · analogy",body:"Greek analogia = proportion, ana- = according to + logos = reason/ratio"},"wd-tautology":{src:"concept:64:words:5:def",route:"#/word/tautology",cta:"Open the word card",title:"tautology",roman:"taw-TOL-uh-jee",body:"(logic) a statement that is necessarily true",clip:1},"wx-tautology":{src:"concept:64:words:5:ex",route:"#/word/tautology",cta:"Open the word card",title:"In a sentence · tautology",body:"The phrase 'a bachelor who has never been married' is a tautology, since the definition of bachelor already includes that meaning.",clip:1},"wh-tautology":{src:"concept:64:words:5:hook",route:"#/word/tautology",cta:"Open the word card",title:"Remember it · tautology",body:"TAUTO means SAME so a TAUTOlogy says the same thing twice"},"wo-tautology":{src:"lore:tautology:0",route:"#/word/tautology",cta:"Open the word card",title:"Where it comes from · tautology",body:"Greek tautologos = repeating what has been said, from tauto (same) + logos (word)"},"wd-eulogy":{src:"concept:64:words:6:def",route:"#/word/eulogy",cta:"Open the word card",title:"eulogy",roman:"y-OO-l-uh-j-ee",body:"is a speech in praise of a dead person",clip:1},"wx-eulogy":{src:"concept:64:words:6:ex",route:"#/word/eulogy",cta:"Open the word card",title:"In a sentence · eulogy",body:"The grieving daughter delivered a heartfelt eulogy that made everyone in the church weep.",clip:1},"wh-eulogy":{src:"concept:64:words:6:hook",route:"#/word/eulogy",cta:"Open the word card",title:"Remember it · eulogy",body:"EUlogy = EU(good)+LOGY(words) — Good Words for the gone; keep EU at the front like 'YOU' speak first."},"wo-eulogy":{src:"lore:eulogy:0",route:"#/word/eulogy",cta:"Open the word card",title:"Where it comes from · eulogy",body:"Greek eu = good + logos = word/speech"},"wd-neologism":{src:"concept:64:words:7:def",route:"#/word/neologism",cta:"Open the word card",title:"neologism",roman:"nee-AH-luh-jih-zum",body:"a newly invented word or phrase",clip:1},"wx-neologism":{src:"concept:64:words:7:ex",route:"#/word/neologism",cta:"Open the word card",title:"In a sentence · neologism",body:"The word 'selfie' began as a neologism but quickly entered dictionaries worldwide.",clip:1},"wh-neologism":{src:"concept:64:words:7:hook",route:"#/word/neologism",cta:"Open the word card",title:"Remember it · neologism",body:"NEOLOGISM ends in ISM—it's the practice of making new words, so end it like 'journalism.'"},"wo-neologism":{src:"lore:neologism:0",route:"#/word/neologism",cta:"Open the word card",title:"Where it comes from · neologism",body:"Greek neos = new + logos = word + -ismos = practice"},"wd-syllogism":{src:"concept:64:words:8:def",route:"#/word/syllogism",cta:"Open the word card",title:"syllogism",roman:"SIL-uh-jiz-um",body:"deductive reasoning in which a conclusion is derived from two premises",clip:1},"wx-syllogism":{src:"concept:64:words:8:ex",route:"#/word/syllogism",cta:"Open the word card",title:"In a sentence · syllogism",body:"The philosopher used a syllogism to prove that all humans are mortal.",clip:1},"wh-syllogism":{src:"concept:64:words:8:hook",route:"#/word/syllogism",cta:"Open the word card",title:"Remember it · syllogism",body:"SylLOGIsm — there's LOGIC inside sylLOGIsm, because it's all about logical reasoning."},"wd-demagogue":{src:"concept:64:words:9:def",route:"#/word/demagogue",cta:"Open the word card",title:"demagogue",roman:"DEH-muh-gahg",body:"a political leader who seeks support by appealing to popular passions and prejudices",clip:1},"wx-demagogue":{src:"concept:64:words:9:ex",route:"#/word/demagogue",cta:"Open the word card",title:"In a sentence · demagogue",body:"The historian warned that the fiery speaker was a demagogue who stirred up fear rather than offering real solutions.",clip:1},"wh-demagogue":{src:"concept:64:words:9:hook",route:"#/word/demagogue",cta:"Open the word card",title:"Remember it · demagogue",body:"A DEMAGOGUE has a silent OGUE at the end — like a rogue leader hiding behind the crowd: dem-a-GOGUE."},"wo-demagogue":{src:"lore:demagogue:0",route:"#/word/demagogue",cta:"Open the word card",title:"Where it comes from · demagogue",body:"Greek demagogos = demos(people) + agogos(leader)"},"wd-pedagogue":{src:"concept:64:words:10:def",route:"#/word/pedagogue",cta:"Open the word card",title:"pedagogue",roman:"PED-uh-gog",body:"someone who educates young people",clip:1},"wx-pedagogue":{src:"concept:64:words:10:ex",route:"#/word/pedagogue",cta:"Open the word card",title:"In a sentence · pedagogue",body:"The old pedagogue paced the classroom, quizzing students on Latin grammar.",clip:1},"wh-pedagogue":{src:"concept:64:words:10:hook",route:"#/word/pedagogue",cta:"Open the word card",title:"Remember it · pedagogue",body:"A PEDAGOGUE has a silent OGUE at the end — like catalogue and synagogue, Greek words love that -OGUE finale."},"wo-pedagogue":{src:"lore:pedagogue:0",route:"#/word/pedagogue",cta:"Open the word card",title:"Where it comes from · pedagogue",body:"Greek paidagogos = child leader; pais = child + agogos = leader"},"wd-theology":{src:"concept:64:words:11:def",route:"#/word/theology",cta:"Open the word card",title:"theology",roman:"thee-AH-luh-jee",body:"the rational and systematic study of religion and its influences and of the nature of religious truth",clip:1},"wx-theology":{src:"concept:64:words:11:ex",route:"#/word/theology",cta:"Open the word card",title:"In a sentence · theology",body:"During her theology course at university, Priya studied how different world religions understand the nature of creation, the divine, and humanity's place in the cosmos.",clip:1},"wh-theology":{src:"concept:64:words:11:hook",route:"#/word/theology",cta:"Open the word card",title:"Remember it · theology",body:"THEOLOGY = THEO (God) + LOGY (study) — just like biology studies life, theology studies God."},"wo-theology":{src:"lore:theology:0",route:"#/word/theology",cta:"Open the word card",title:"Where it comes from · theology",body:"Greek theos = god + logos = study"},"wd-catalog":{src:"concept:64:words:12:def",route:"#/word/catalog",cta:"Open the word card",title:"catalog",roman:"KA-tuh-lawg",body:"a book or pamphlet containing an enumeration of things",clip:1},"wx-catalog":{src:"concept:64:words:12:ex",route:"#/word/catalog",cta:"Open the word card",title:"In a sentence · catalog",body:"he found it in the Sears catalog",clip:1},"wh-catalog":{src:"concept:64:words:12:hook",route:"#/word/catalog",cta:"Open the word card",title:"Remember it · catalog",body:"A CATALOG LOGS items down the page — CATA+LOG, the American spelling drops the UE."},"wo-catalog":{src:"lore:catalog:0",route:"#/word/catalog",cta:"Open the word card",title:"Where it comes from · catalog",body:"Greek katalogos = list, from kata- = down + legein = to reckon"},"wd-travelogue":{src:"concept:64:words:13:def",route:"#/word/travelogue",cta:"Open the word card",title:"travelogue",roman:"TRA-vuh-lawg",body:"a film or illustrated lecture on traveling",clip:1},"wx-travelogue":{src:"concept:64:words:13:ex",route:"#/word/travelogue",cta:"Open the word card",title:"In a sentence · travelogue",body:"The geography teacher showed a captivating travelogue about life along the Amazon River.",clip:1},"wh-travelogue":{src:"concept:64:words:13:hook",route:"#/word/travelogue",cta:"Open the word card",title:"Remember it · travelogue",body:"A traveLOGue is a LOG of your travels — the -OGUE wraps it up like a catalogue."},"wo-travelogue":{src:"lore:travelogue:0",route:"#/word/travelogue",cta:"Open the word card",title:"Where it comes from · travelogue",body:"travel + Greek logos = word/account"},"wd-apology":{src:"concept:64:words:14:def",route:"#/word/apology",cta:"Open the word card",title:"apology",roman:"uh-PAH-luh-jee",body:"an expression of regret at having caused trouble for someone",clip:1},"wx-apology":{src:"concept:64:words:14:ex",route:"#/word/apology",cta:"Open the word card",title:"In a sentence · apology",body:"Marcus offered a sincere apology to his teammate after accidentally knocking him down during practice.",clip:1},"wh-apology":{src:"concept:64:words:14:hook",route:"#/word/apology",cta:"Open the word card",title:"Remember it · apology",body:"aPOLogy — say SORRY, it's POLite"},"wo-apology":{src:"lore:apology:0",route:"#/word/apology",cta:"Open the word card",title:"Where it comes from · apology",body:"Greek 'apologia' = a speech in defense, from 'apo-' = away + 'logos' = speech"},"li-u62":{src:"concept:65:concept",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love)",body:"Greek philein = to love. Phil- appears at the start of words; -phile appears at the end. Together they create the vocabulary of love and affinity — for ideas, books, countries, and knowledge itself."},"lc-u62-0":{src:"concept:65:cards:0",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love) · The Root",body:"Greek philein = to love → phil- (at start) or -phile (at end). Philanthropy (phil + anthropos = human) = love of humanity. Philosophy (phil + sophia = wisdom) = love of wisdom. Philharmonic (phil + harmonikos) = loving harmony. Bibliophile (biblio = book + -phile) = one who loves books."},"lc-u62-1":{src:"concept:65:cards:1",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love) · -phile = One Who Loves",body:"Bibliophile = loves books. Anglophile = loves England/British culture. Francophile = loves French culture. Francophobe = fears/dislikes French culture (-phobe = opposite of -phile). Oenophile (oinos = wine) = loves wine. Cinephile = loves films. Xenophile (xenos = strange) = loves foreign things."},"lc-u62-2":{src:"concept:65:cards:2",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love) · -philia = Love of (as condition)",body:"Hemophilia (hemo- = blood + -philia) = love of blood = condition where blood does not clot. Bibliophilia = passionate love of books. Anglophilia = love of things English. The -philia form denotes the condition or tendency rather than the person."},"lc-u62-3":{src:"concept:65:cards:3",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love) · Philadelphia — the City of Brotherly Love",body:"Philadelphia (philos = loving + adelphos = brother) = city of brotherly love. The name is pure Greek etymology alive in American geography. Similarly: Philip (philippos) = philos + hippos = lover of horses. Philosophy = philos + sophia = lover of wisdom."},"lc-u62-4":{src:"concept:65:cards:4",route:"#/stop/u62",cta:"Open this stop",title:"phil / phile (love) · Spelling the phil- Words",body:"Always ph not f — this is Greek and the ph is non-negotiable. Philanthropy = P-H-I-L-A-N-T-H-R-O-P-Y (two ph units — the -ph- in phil and the -p-h- from anthropos). Philosophy = P-H-I-L-O-S-O-P-H-Y (again two ph units). Count the Greek ph's carefully."},"uq-u62-3":{src:"unit:u62:qs:3",route:"#/stop/u62",cta:"Open this stop",title:"Whose hook?",play:{q:"“PHIL loves ANTHROP-ology, so he gives generously — ▁▁▁ = love of humanity.” — which word is this hook about?",opts:["philanthropy","philosophy","philharmonic","bibliophile"],after:"From “phil / phile (love)”."}},"wd-philanthropy":{src:"concept:65:words:0:def",route:"#/word/philanthropy",cta:"Open the word card",title:"philanthropy",roman:"fih-LA-nthruh-pee",body:"voluntary promotion of human welfare",clip:1},"wx-philanthropy":{src:"concept:65:words:0:ex",route:"#/word/philanthropy",cta:"Open the word card",title:"In a sentence · philanthropy",body:"The billionaire devoted her retirement to philanthropy, donating millions to build schools in underserved communities around the world.",clip:1},"wh-philanthropy":{src:"concept:65:words:0:hook",route:"#/word/philanthropy",cta:"Open the word card",title:"Remember it · philanthropy",body:"PHIL loves ANTHROP-ology, so he gives generously — PHILanthropY = love of humanity."},"wo-philanthropy":{src:"lore:philanthropy:0",route:"#/word/philanthropy",cta:"Open the word card",title:"Where it comes from · philanthropy",body:"Greek philanthropia = love of mankind (philos=loving + anthropos=human)"},"wd-philosophy":{src:"concept:65:words:1:def",route:"#/word/philosophy",cta:"Open the word card",title:"philosophy",roman:"fuh-LAH-suh-fee",body:"a belief (or system of beliefs) accepted as authoritative by some group or school",clip:1},"wx-philosophy":{src:"concept:65:words:1:ex",route:"#/word/philosophy",cta:"Open the word card",title:"In a sentence · philosophy",body:"self-indulgence was his only philosophy",clip:1},"wh-philosophy":{src:"concept:65:words:1:hook",route:"#/word/philosophy",cta:"Open the word card",title:"Remember it · philosophy",body:"PHIL-O-SOPH-Y: Phil loves Sophie — no letters skipped between them."},"wd-anglophile":{src:"concept:65:words:4:def",route:"#/word/anglophile",cta:"Open the word card",title:"anglophile",roman:"A-ngluh-feyel",body:"an admirer of England and things English",clip:1},"wx-anglophile":{src:"concept:65:words:4:ex",route:"#/word/anglophile",cta:"Open the word card",title:"In a sentence · anglophile",body:"As an anglophile, she decorated her room with images of Big Ben, drank tea every afternoon, and spoke with a slight British accent.",clip:1},"wh-anglophile":{src:"concept:65:words:4:hook",route:"#/word/anglophile",cta:"Open the word card",title:"Remember it · anglophile",body:"ANGLO + PHILE — a phile (lover) of all things ANGLO (English)"},"wo-anglophile":{src:"lore:anglophile:0",route:"#/word/anglophile",cta:"Open the word card",title:"Where it comes from · anglophile",body:"Latin Anglus = English + Greek philos = loving"},"wd-francophile":{src:"concept:65:words:5:def",route:"#/word/francophile",cta:"Open the word card",title:"francophile",roman:"FRA-ngkuh-feyel",body:"an admirer of France and everything French",clip:1},"wx-francophile":{src:"concept:65:words:5:ex",route:"#/word/francophile",cta:"Open the word card",title:"In a sentence · francophile",body:"A true francophile, Mr. Dupont decorated his classroom with Eiffel Tower posters and played French jazz every morning.",clip:1},"wh-francophile":{src:"concept:65:words:5:hook",route:"#/word/francophile",cta:"Open the word card",title:"Remember it · francophile",body:"A FRANCOPHILE loves FRANCE — FRANCO + PHILE (lover), no K anywhere: F-R-A-N-C-O-P-H-I-L-E."},"wo-francophile":{src:"lore:francophile:0",route:"#/word/francophile",cta:"Open the word card",title:"Where it comes from · francophile",body:"French Franc = French + Greek philos = lover"},"wd-oenophile":{src:"concept:65:words:6:def",route:"#/word/oenophile",cta:"Open the word card",title:"oenophile",roman:"EE-nuh-feyel",body:"someone who appreciates wine",clip:1},"wx-oenophile":{src:"concept:65:words:6:ex",route:"#/word/oenophile",cta:"Open the word card",title:"In a sentence · oenophile",body:"The oenophile spent hours studying the vineyard's soil before selecting the perfect bottle.",clip:1},"wh-oenophile":{src:"concept:65:words:6:hook",route:"#/word/oenophile",cta:"Open the word card",title:"Remember it · oenophile",body:"An OENOphile loves OENology — both start with OENO; a wine lover has an OE-nose for fine vintages."},"wo-oenophile":{src:"lore:oenophile:0",route:"#/word/oenophile",cta:"Open the word card",title:"Where it comes from · oenophile",body:"Greek oinos = wine + philos = lover"},"wd-cinephile":{src:"concept:65:words:7:def",route:"#/word/cinephile",cta:"Open the word card",title:"cinephile",roman:"SIN-uh-fyl",body:"A person who is extremely enthusiastic about and knowledgeable in the art of cinema and film history.",clip:1},"wx-cinephile":{src:"concept:65:words:7:ex",route:"#/word/cinephile",cta:"Open the word card",title:"In a sentence · cinephile",body:"As a true cinephile, Marcus had watched over five hundred films before finishing middle school.",clip:1},"wh-cinephile":{src:"concept:65:words:7:hook",route:"#/word/cinephile",cta:"Open the word card",title:"Remember it · cinephile",body:"CINE + PHILE — a phile loves things, and a cinephile loves cinema."},"wd-hemophilia":{src:"concept:65:words:9:def",route:"#/word/hemophilia",cta:"Open the word card",title:"hemophilia",roman:"hee-muh-FEE-lee-uh",body:"congenital tendency to uncontrolled bleeding; usually affects males and is transmitted from mother to son",clip:1},"wx-hemophilia":{src:"concept:65:words:9:ex",route:"#/word/hemophilia",cta:"Open the word card",title:"In a sentence · hemophilia",body:"Because he had hemophilia, even a minor cut required immediate medical attention to stop the bleeding.",clip:1},"wh-hemophilia":{src:"concept:65:words:9:hook",route:"#/word/hemophilia",cta:"Open the word card",title:"Remember it · hemophilia",body:"Hemophilia: blood has a 'philia' (love) for flowing — it just won't stop."},"wo-hemophilia":{src:"lore:hemophilia:0",route:"#/word/hemophilia",cta:"Open the word card",title:"Where it comes from · hemophilia",body:"Greek haima = blood + philia = love/affinity"},"wd-bibliophilia":{src:"concept:65:words:11:def",route:"#/word/bibliophilia",cta:"Open the word card",title:"bibliophilia",roman:"bib-lee-oh-FIL-ee-uh",body:"A deep love of books and reading; the passionate enthusiasm for collecting, appreciating, and studying books as objects of beauty and knowledge.",clip:1},"wx-bibliophilia":{src:"concept:65:words:11:ex",route:"#/word/bibliophilia",cta:"Open the word card",title:"In a sentence · bibliophilia",body:"Her bibliophilia was evident from the towering stacks of books that covered every surface of her bedroom.",clip:1},"wh-bibliophilia":{src:"concept:65:words:11:hook",route:"#/word/bibliophilia",cta:"Open the word card",title:"Remember it · bibliophilia",body:"BIBLIO (book) + PHILIA (love) — book LOVE, like Philadelphia means 'brotherly love' but for BOOKS."},"wd-philology":{src:"concept:65:words:12:def",route:"#/word/philology",cta:"Open the word card",title:"philology",roman:"fih-LOL-oh-jee",body:"the humanistic study of language and literature",clip:1},"wx-philology":{src:"concept:65:words:12:ex",route:"#/word/philology",cta:"Open the word card",title:"In a sentence · philology",body:"Her passion for philology led her to trace the surprising origins of dozens of everyday English words.",clip:1},"wh-philology":{src:"concept:65:words:12:hook",route:"#/word/philology",cta:"Open the word card",title:"Remember it · philology",body:"PhiloLOGY loves LOGOS — words and language; one L, like a single well-chosen word."},"wo-philology":{src:"lore:philology:0",route:"#/word/philology",cta:"Open the word card",title:"Where it comes from · philology",body:"Greek philologia = love of words (philos=loving + logos=word)"},"wd-philosophic":{src:"concept:65:words:13:def",route:"#/word/philosophic",cta:"Open the word card",title:"philosophic",roman:"fih-luh-SAH-fihk",body:"of or relating to philosophy or philosophers",clip:1},"wx-philosophic":{src:"concept:65:words:13:ex",route:"#/word/philosophic",cta:"Open the word card",title:"In a sentence · philosophic",body:"philosophical writing",clip:1},"wh-philosophic":{src:"concept:65:words:13:hook",route:"#/word/philosophic",cta:"Open the word card",title:"Remember it · philosophic",body:"Phil loves Sophie's wisdom — PHILo+SOPHic."},"wo-philosophic":{src:"lore:philosophic:0",route:"#/word/philosophic",cta:"Open the word card",title:"Where it comes from · philosophic",body:"Greek philos=loving + sophia=wisdom"},"wd-philanthropist":{src:"concept:65:words:14:def",route:"#/word/philanthropist",cta:"Open the word card",title:"philanthropist",roman:"fuh-LA-nthruh-puhst",body:"someone who makes charitable donations intended to increase human well-being",clip:1},"wx-philanthropist":{src:"concept:65:words:14:ex",route:"#/word/philanthropist",cta:"Open the word card",title:"In a sentence · philanthropist",body:"The philanthropist donated enough money to build a new library for every school in the district.",clip:1},"wh-philanthropist":{src:"concept:65:words:14:hook",route:"#/word/philanthropist",cta:"Open the word card",title:"Remember it · philanthropist",body:"A philanthropIST puts people on his LIST of those to help — no H after anthrop!"},"li-u63":{src:"concept:66:concept",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce)",body:"Greek genos = birth, race, kind → Latin borrowed it as genus. This root appears in biology, chemistry, medicine, and genealogy — any time words discuss origins, kinds, or creation."},"lc-u63-0":{src:"concept:66:cards:0",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce) · The Root",body:"Greek genos = birth, race, kind. Genesis = the beginning = origin. Genealogy = study of family origins. Generate = to bring into being. Genetics = the science of inherited characteristics. Genre (genos through French) = a kind or category. One root, from family trees to gene science."},"lc-u63-1":{src:"concept:66:cards:1",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce) · -gen = Producing",body:"In chemistry, -gen = something that produces. Hydrogen (hydro + gen) = produces water (H₂O). Oxygen (oxys = sharp/acid + gen) = produces acid (original belief). Nitrogen (nitron = saltpeter + gen) = produces saltpeter. Pathogen = produces disease. Carcinogen = produces cancer."},"lc-u63-2":{src:"concept:66:cards:2",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce) · -genic = Producing / Born",body:'Photogenic = born/suited for photographs. Pathogenic = disease-producing. Carcinogenic = cancer-producing. Telegenic = suited for television. Psychogenic = originating in the mind. Neurogenic = originating in nerve tissue. The suffix -genic = "producing" or "of that origin."'},"lc-u63-3":{src:"concept:66:cards:3",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce) · Homogeneous vs Heterogeneous",body:"Homogeneous (homo = same + genos = kind) = of the same kind throughout. Heterogeneous (hetero = different + genos) = of different kinds. Both appear in chemistry, biology, and everyday language. The contrast pair uses the same root with opposite prefixes."},"lc-u63-4":{src:"concept:66:cards:4",route:"#/stop/u63",cta:"Open this stop",title:"gen / genesis (birth / origin / produce) · Genus & Genre",body:"Latin genus = kind/class (from Greek genos). Genus in biology = a classification level above species. Genre = a type/category (music genre, literary genre). Congenital (con- + genitus = born with) = existing from birth. Indigenous (indu- = within + gen- = born) = born within the land = native."},"uq-u63-0":{src:"unit:u63:qs:0",route:"#/stop/u63",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “gen / genesis (birth / origin / produce)”?",opts:["Greek genos = birth, race, kind → Latin borrowed it as genus.","Old English/Latin un- = not (before adjectives) or reverse the action of (before verbs).","Latin com- = with, together.","The most common suffix in English — from Latin -tionem."],after:"From “gen / genesis (birth / origin / produce)”."}},"uq-u63-3":{src:"unit:u63:qs:3",route:"#/stop/u63",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: your GENE family LOG — remember the 'a' sits between gene and logy like an ancestor link.” — which word is this hook about?",opts:["genealogy","genesis","genetics","generate"],after:"From “gen / genesis (birth / origin / produce)”."}},"wd-genealogy":{src:"concept:66:words:0:def",route:"#/word/genealogy",cta:"Open the word card",title:"genealogy",roman:"jee-nee-AH-luh-jee",body:"successive generations of kin",clip:1},"wx-genealogy":{src:"concept:66:words:0:ex",route:"#/word/genealogy",cta:"Open the word card",title:"In a sentence · genealogy",body:"After months of research into her genealogy, Mira discovered she was distantly related to a famous explorer.",clip:1},"wh-genealogy":{src:"concept:66:words:0:hook",route:"#/word/genealogy",cta:"Open the word card",title:"Remember it · genealogy",body:"GENEaLOGY: your GENE family LOG — remember the 'a' sits between gene and logy like an ancestor link."},"wo-genealogy":{src:"lore:genealogy:0",route:"#/word/genealogy",cta:"Open the word card",title:"Where it comes from · genealogy",body:"Greek genea = generation + logos = study"},"wd-genesis":{src:"concept:66:words:1:def",route:"#/word/genesis",cta:"Open the word card",title:"genesis",roman:"JEH-nuh-suhs",body:"a coming into being",clip:1},"wx-genesis":{src:"concept:66:words:1:ex",route:"#/word/genesis",cta:"Open the word card",title:"In a sentence · genesis",body:"Scientists still debate the genesis of the universe and what existed before the Big Bang.",clip:1},"wh-genesis":{src:"concept:66:words:1:hook",route:"#/word/genesis",cta:"Open the word card",title:"Remember it · genesis",body:"Genesis is the origin — the 'e' in the middle echoes 'begin': the beginning of all things."},"wd-genetics":{src:"concept:66:words:2:def",route:"#/word/genetics",cta:"Open the word card",title:"genetics",roman:"juh-NEH-tihks",body:"the branch of biology that studies heredity and variation in organisms",clip:1},"wx-genetics":{src:"concept:66:words:2:ex",route:"#/word/genetics",cta:"Open the word card",title:"In a sentence · genetics",body:"Her fascination with genetics led her to study how inherited traits are passed from parents to children.",clip:1},"wh-genetics":{src:"concept:66:words:2:hook",route:"#/word/genetics",cta:"Open the word card",title:"Remember it · genetics",body:"GENETICS begins with GENE — because genes are what this science is all about."},"wo-genetics":{src:"lore:genetics:0",route:"#/word/genetics",cta:"Open the word card",title:"Where it comes from · genetics",body:"Greek genesis = origin, birth"},"wd-generate":{src:"concept:66:words:3:def",route:"#/word/generate",cta:"Open the word card",title:"generate",roman:"JEH-ner-ayt",body:"bring into existence",clip:1},"wx-generate":{src:"concept:66:words:3:ex",route:"#/word/generate",cta:"Open the word card",title:"In a sentence · generate",body:"The new manager generated a lot of problems",clip:1},"wh-generate":{src:"concept:66:words:3:hook",route:"#/word/generate",cta:"Open the word card",title:"Remember it · generate",body:"Generate keeps 'gene' at the start — genes generate life, so remember the spelling that way."},"wo-generate":{src:"lore:generate:0",route:"#/word/generate",cta:"Open the word card",title:"Where it comes from · generate",body:"Latin generare = to beget/produce"},"wd-hydrogen":{src:"concept:66:words:4:def",route:"#/word/hydrogen",cta:"Open the word card",title:"hydrogen",roman:"HEYE-druh-juhn",body:"a nonmetallic univalent element that is normally a colorless and odorless highly flammable diatomic gas; the simplest and lightest and most abundant element in the universe",clip:1},"wx-hydrogen":{src:"concept:66:words:4:ex",route:"#/word/hydrogen",cta:"Open the word card",title:"In a sentence · hydrogen",body:"Hydrogen is the lightest element on the periodic table and makes up most of the universe's visible matter.",clip:1},"wh-hydrogen":{src:"concept:66:words:4:hook",route:"#/word/hydrogen",cta:"Open the word card",title:"Remember it · hydrogen",body:"HydroGEN GENerates water when burned — it's the water-making GENius of the periodic table."},"wo-hydrogen":{src:"lore:hydrogen:0",route:"#/word/hydrogen",cta:"Open the word card",title:"Where it comes from · hydrogen",body:"Greek hydor = water + genes = producing"},"wd-nitrogen":{src:"concept:66:words:6:def",route:"#/word/nitrogen",cta:"Open the word card",title:"nitrogen",roman:"n-AY-t-r-uh-j-uh-n",body:"a common nonmetallic element that constitutes 78 percent of the atmosphere",clip:1},"wx-nitrogen":{src:"concept:66:words:6:ex",route:"#/word/nitrogen",cta:"Open the word card",title:"In a sentence · nitrogen",body:"Plants need nitrogen to grow, which is why farmers often add special fertilizers to their soil.",clip:1},"wh-nitrogen":{src:"concept:66:words:6:hook",route:"#/word/nitrogen",cta:"Open the word card",title:"Remember it · nitrogen",body:"NITROgen GENErates the air — remember the 'e' in gen, like 'generate.'"},"wo-nitrogen":{src:"lore:nitrogen:0",route:"#/word/nitrogen",cta:"Open the word card",title:"Where it comes from · nitrogen",body:"Greek nitron = niter (saltpeter) + genes = producing"},"wd-carcinogen":{src:"concept:66:words:8:def",route:"#/word/carcinogen",cta:"Open the word card",title:"carcinogen",roman:"kah-RSIH-nuh-juhn",body:"any substance that produces cancer",clip:1},"wx-carcinogen":{src:"concept:66:words:8:ex",route:"#/word/carcinogen",cta:"Open the word card",title:"In a sentence · carcinogen",body:"Scientists confirmed that the chemical released by the factory was a carcinogen linked to higher cancer rates in the area.",clip:1},"wh-carcinogen":{src:"concept:66:words:8:hook",route:"#/word/carcinogen",cta:"Open the word card",title:"Remember it · carcinogen",body:"A carCINogen CINches cancer — remember the 'c' not 's' because Cancer starts with C."},"wo-carcinogen":{src:"lore:carcinogen:0",route:"#/word/carcinogen",cta:"Open the word card",title:"Where it comes from · carcinogen",body:"Greek karkinos = crab/cancer + gennan = to produce"},"wd-pathogenic":{src:"concept:66:words:10:def",route:"#/word/pathogenic",cta:"Open the word card",title:"pathogenic",roman:"pa-thuh-JEH-nihk",body:"able to cause disease",clip:1},"wx-pathogenic":{src:"concept:66:words:10:ex",route:"#/word/pathogenic",cta:"Open the word card",title:"In a sentence · pathogenic",body:"Scientists studying the pathogenic bacteria discovered that it spread rapidly in warm, humid environments, making proper handwashing and sanitation the most effective ways to prevent infection.",clip:1},"wh-pathogenic":{src:"concept:66:words:10:hook",route:"#/word/pathogenic",cta:"Open the word card",title:"Remember it · pathogenic",body:"PATHogenic things GENerate Illness — PATH + O + GEN + IC, four clean blocks."},"wo-pathogenic":{src:"lore:pathogenic:0",route:"#/word/pathogenic",cta:"Open the word card",title:"Where it comes from · pathogenic",body:"Greek pathos = disease + genos = producing"},"wd-carcinogenic":{src:"concept:66:words:11:def",route:"#/word/carcinogenic",cta:"Open the word card",title:"carcinogenic",roman:"kah-rsuh-noh-JEH-nihk",body:"causing or tending to cause cancer",clip:1},"wx-carcinogenic":{src:"concept:66:words:11:ex",route:"#/word/carcinogenic",cta:"Open the word card",title:"In a sentence · carcinogenic",body:"Scientists confirmed that the factory had been releasing carcinogenic chemicals into the river for years, putting the health of nearby residents at serious risk.",clip:1},"wh-carcinogenic":{src:"concept:66:words:11:hook",route:"#/word/carcinogenic",cta:"Open the word card",title:"Remember it · carcinogenic",body:"CARCINO (cancer) + GENIC (producing) — carcinogenic produces cancer"},"wo-carcinogenic":{src:"lore:carcinogenic:0",route:"#/word/carcinogenic",cta:"Open the word card",title:"Where it comes from · carcinogenic",body:"Greek karkinos = crab, cancer + genesis = origin, creation"},"wd-homogeneous":{src:"concept:66:words:12:def",route:"#/word/homogeneous",cta:"Open the word card",title:"homogeneous",roman:"hoh-muh-JEE-nee-uhs",body:"all of the same or similar kind or nature",clip:1},"wx-homogeneous":{src:"concept:66:words:12:ex",route:"#/word/homogeneous",cta:"Open the word card",title:"In a sentence · homogeneous",body:"a close-knit homogeneous group",clip:1},"wh-homogeneous":{src:"concept:66:words:12:hook",route:"#/word/homogeneous",cta:"Open the word card",title:"Remember it · homogeneous",body:"HomoGENEous — if everything shares the same GENE, the mixture is perfectly uniform and homogeneous."},"wo-homogeneous":{src:"lore:homogeneous:0",route:"#/word/homogeneous",cta:"Open the word card",title:"Where it comes from · homogeneous",body:"Greek homos = same + genos = kind"},"wd-heterogeneous":{src:"concept:66:words:13:def",route:"#/word/heterogeneous",cta:"Open the word card",title:"heterogeneous",roman:"h-eh-t-ur-uh-j-EE-n-y-uh-s",body:"is different in kind unlike",clip:1}});
